include "globals.mzn";

enum COLOR = {red, green, ivory, yellow, blue};
enum NATIONALITY = {englishman, ukrainian, norwegian, japanese, spaniard};
enum DRINK = {coffee, tea, milk, orangeJuice, water};
enum CIGAR = {oldGold, kools, chesterfields, luckyStrike, parliaments};
enum PET = {dog, snails, fox, horse, zebra};

int: N = 5;

array[1..N] of var COLOR: color;
array[1..N] of var NATIONALITY: nationality;
array[1..N] of var DRINK: drink;
array[1..N] of var CIGAR: cigar;
array[1..N] of var PET: pet;

% Clue 1: The Englishman lives in the red house.
constraint forall(i in 1..N)(nationality[i] = englishman -> color[i] = red);

% Clue 2: The Spaniard owns the dog.
constraint forall(i in 1..N)(nationality[i] = spaniard -> pet[i] = dog);

% Clue 3: Coffee is drunk in the green house.
constraint forall(i in 1..N)(color[i] = green -> drink[i] = coffee);

% Clue 4: The Ukrainian drinks tea.
constraint forall(i in 1..N)(nationality[i] = ukrainian -> drink[i] = tea);

% Clue 5: The green house is immediately to the right of the ivory house.
constraint forall(i in 1..N-1)(color[i] = ivory -> color[i+1] = green);

% Clue 6: The Old Gold smoker owns snails.
constraint forall(i in 1..N)(cigar[i] = oldGold -> pet[i] = snails);

% Clue 7: Kools are smoked in the yellow house.
constraint forall(i in 1..N)(color[i] = yellow -> cigar[i] = kools);

% Clue 8: Milk is drunk in the middle house.
constraint drink[3] = milk;

% Clue 9: The Norwegian lives in the first house.
constraint nationality[1] = norwegian;

% Clue 10: The man who smokes Chesterfields lives in the house next to the man with the fox.
constraint exists(i in 1..N-1)(cigar[i] = chesterfields /\ pet[i+1] = fox) \/ 
         exists(i in 2..N)(cigar[i] = chesterfields /\ pet[i-1] = fox);

% Clue 11: Kools are smoked in the house next to the house where the horse is kept.
constraint exists(i in 1..N-1)(cigar[i] = kools /\ pet[i+1] = horse) \/ 
         exists(i in 2..N)(cigar[i] = kools /\ pet[i-1] = horse);

% Clue 12: The Lucky Strike smoker drinks orange juice.
constraint forall(i in 1..N)(cigar[i] = luckyStrike -> drink[i] = orangeJuice);

% Clue 13: The Japanese smokes Parliaments.
constraint forall(i in 1..N)(nationality[i] = japanese -> cigar[i] = parliaments);

% Clue 14: The Norwegian lives next to the blue house.
constraint exists(i in 1..N-1)(nationality[i] = norwegian /\ color[i+1] = blue) \/ 
         exists(i in 2..N)(nationality[i] = norwegian /\ color[i-1] = blue);

% Ensure all properties (colors, nationalities, drinks, cigars, pets) are different
constraint alldifferent(color);
constraint alldifferent(nationality);
constraint alldifferent(drink);
constraint alldifferent(cigar);
constraint alldifferent(pet);

% Enforce distinct nationalities for further uniqueness
constraint forall(i in 1..N)(nationality[i] != nationality[i+1]);

% Add an additional constraint for the green house to enforce that it must drink coffee correctly
constraint forall(i in 1..N)(color[i] = green -> drink[i] = coffee);

solve satisfy;

% Output for water and zebra
output [
    show(nationality[max(i | drink[i] = water)]) ++ " drinks water.\n",
    show(nationality[max(i | pet[i] = zebra)]) ++ " owns the zebra."
];

